// Blocked: "Account blocked"
// Wrong credentials: "Invalid credentials"
// Sab sahi: "Welcome back"

solution:
function loginStatus(username, password, isBlocked) {
  if (isBlocked) return "Account blocked"
  if (username !== "admin" || password !== "1234") return "Invalid credentials"
  return "Welcome back"
}
